INSERT INTO "tb_operate" ("id", "operate_name", "device_type", "manufacturer", "engine_type", "service_type", "engine_param", "extend_param", "data_type", "operate_mode", "polling", "timeout", "create_time", "update_time") VALUES
	(1, 'foxLibs', 'CE+T UPS V3.0', '深圳安圣电气有限公司', 'JavaScript', 'device', '{"include":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 数组的拷贝\n *\n * @param srcUint8Array\n * @param srcPos\n * @param dstUint8Array\n * @param dstPos\n * @param length\n */\nfunction arraycopy(srcUint8Array, srcPos, dstUint8Array, dstPos, length) {\n    var src = srcPos;\n    var dst = dstPos;\n    for (var index = 0; index \u003c length; index++, src++, dst++) {\n        dstUint8Array[dst] = srcUint8Array[src];\n    }\n}\n\n/**\n * 数组转换为hex\n *\n * @param uint8Array\n * @returns {string}\n */\nfunction arrayToHex(uint8Array) {\n    var hex = \"\";\n    for (var i = 0; i \u003c uint8Array.length; i++) {\n        var ch = uint8Array[i].toString(16);\n        hex += padStart(ch, 2, ''0'').toUpperCase();\n    }\n\n    return hex;\n}\n\n/**\n * hex转数组\n * @param hex\n * @returns {Uint8Array}\n */\nfunction hexToArray(hex) {\n    var hex = hex.replace(/\\s+/g, \"\").toUpperCase();\n    var uint8Array = new Uint8Array(hex.length / 2);\n    for (var i = 0; i \u003c uint8Array.length; i++) {\n        uint8Array[i] = parseInt(hex[2 * i] + hex[2 * i + 1], 16);\n    }\n\n    return uint8Array;\n}\n\n/**\n * 替代JS旧版本不支持的padStart函数\n *\n * @param str\n * @param length\n * @param ch\n * @returns {*}\n */\nfunction padStart(str, length, ch) {\n    while (str.length \u003c length) {\n        str = ch + str;\n    }\n\n    return str;\n}\n\n/**\n * CRC16校验\n * 范例：var crc16 = calculateCRC16(data, 0, data.length - 2, 0xFFFF, 0xA001);\n *\n * @param bytes Uint8Array格式的数组\n * @param offset 数组的偏移量\n * @param length 需要计算的长度\n * @param init CRC16的初始值，例如：0x0000\n * @param poly CRC16的多项式，例如：0xA001\n * @returns {number} CRC16\n */\nfunction calculateCRC16(bytes, offset, length, init, poly) {\n    var crc = init;\n    var polynomial = poly;  // This is the polynomial x^16 + x^15 + x^2 + 1\n\n    for (var i = offset; i \u003c length; i++) {\n        crc ^= bytes[i];\n        for (var j = 0; j \u003c 8; j++) {\n            if (crc \u0026 0x0001) {\n                crc = ((crc \u003e\u003e 1) ^ polynomial) \u0026 0xFFFF;\n            } else {\n                crc \u003e\u003e= 1;\n            }\n        }\n    }\n\n    return crc \u0026 0xffff\n}\n\n/**\n * IEEE754浮点数的转换\n * 说明：32位浮点（数默认格式：低位在前，高位在后）\n * 测试范例：45 0f 60 00 数值位2294.0\n * bitsToFloat(0x00, 0x60, 0x0f, 0x45) = 2294.0\n *\n * @param bit3\n * @param bit2\n * @param bit1\n * @param bit0\n * @returns {number}\n */\nfunction bitsToFloat(bit3, bit2, bit1, bit0) {\n    var bits = (bit0 \u003c\u003c 24) | (bit1 \u003c\u003c 16) | (bit2 \u003c\u003c 8) | (bit3);\n    var sign = ((bits \u003e\u003e\u003e 31) == 0) ? 1.0 : -1.0;\n    var e = ((bits \u003e\u003e\u003e 23) \u0026 0xff);\n    var m = (e == 0) ? (bits \u0026 0x7fffff) \u003c\u003c 1 : (bits \u0026 0x7fffff) | 0x800000;\n    var f = sign * m * Math.pow(2, e - 150);\n    return f;\n}\n\n/**\n * 判定是否存在Empty的参数\n *\n * @param arg\n * @returns {boolean}\n */\nfunction testEmpty(arg, error) {\n    if ((arg == undefined || arg == null || arg === '''')) {\n        throw Error(error);\n    }\n}\n","main":"include"}}', '{"description":"Fox-Edge提供的常用公共库JS函数。\n\n它的目的，是提供JS开发者们写解码器的时候，会用到的许多常用函数，避免不必要的重复性开发工作"}', 'status', 'include', 1, 2000, 1732883941029, 1732883941029),
	(2, 'modbusCoreLibs', 'CE+T UPS V3.0', '深圳安圣电气有限公司', 'JavaScript', 'device', '{"include":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n\n\n/**\n * 写寄存器编码器请求\n *\n * @param param\n * @returns {Uint8Array}\n */\nfunction encodeWriteRegistersRequest(param) {\n    // 检测：输入参数释放合法\n    testUserParam(param);\n\n    var pduEntity = newPduEntity();\n    pduEntity.func = 0x06;\n    pduEntity.devAddr = param.devAddr;\n\n    // 检测：是否有流水号参数\n    if (param.sn != undefined \u0026\u0026 param.sn != null) {\n        pduEntity.sn = param.sn;\n    }\n\n    // 检测：是否有流水号参数\n    if (param.value == undefined || param.value == null) {\n        throw new Error(\"实体字段为空：value\");\n    }\n\n    if (param.regCnt == 1) {\n        // 设置单个寄存器\n        pduEntity.func = 0x06;\n        pduEntity.data = new Uint8Array(4);\n        // 寄存器起始地址\n        pduEntity.data[0] = param.regAddr / 0x100;\n        pduEntity.data[1] = param.regAddr % 0x100;\n        // 单个寄存器\n        pduEntity.data[2] = param.value / 0x100;\n        pduEntity.data[3] = param.value % 0x100;\n    }\n    if (param.regCnt \u003e 1) {\n        // 设置多个寄存器\n        pduEntity.func = 0x10;\n        pduEntity.data = new Uint8Array(5 + param.regCnt * 2);\n        // 寄存器起始地址\n        pduEntity.data[0] = param.regAddr / 0x100;\n        pduEntity.data[1] = param.regAddr % 0x100;\n        // 寄存器数量\n        pduEntity.data[2] = param.regCnt / 0x100;\n        pduEntity.data[3] = param.regCnt % 0x100;\n        // 寄存器数据的长度\n        pduEntity.data[4] = param.regCnt * 2;\n        // 连续寄存器的内容\n        for (var index = 0; index \u003c param.regCnt; index++) {\n            pduEntity.data[5 + index * 2] = param.value[0 + index * 2];\n            pduEntity.data[6 + index * 2] = param.value[1 + index * 2];\n        }\n    }\n\n    return encodePdu(pduEntity, param.modbusMode);\n}\n\n/**\n * 解码写寄存器\n *\n * @param pdu\n * @param param\n * @returns {{status: *[]}}\n */\nfunction decodeWriteRegistersRespond(pdu, param) {\n    // 报文解码\n    var pduEntity = decodePdu(pdu, param.modbusMode);\n\n\n    if (pduEntity.func == 0x86 \u0026\u0026 pduEntity.data.length \u003e 0) {\n        pduEntity.errCode = pduEntity.data[0];\n        pduEntity.errMsg = getError(pduEntity.data[0]);\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    // 检测是否为输入0x06的返回\n    if (pduEntity.func != 0x06 \u0026\u0026 pduEntity.func != 0x10) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    // 检测：数据长度\n    if (pduEntity.data.length != 4) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    var respond = {\n        value: 0\n    };\n\n    respond.regAddr = (((pduEntity.data[0] \u0026 0xff) * 0x100) + (pduEntity.data[1] \u0026 0xff));\n    respond.value = (((pduEntity.data[2] \u0026 0xff) * 0x100) + (pduEntity.data[3] \u0026 0xff));\n\n    return respond;\n}\n\n/**\n * 写寄存器编码器请求\n *\n * @param param\n * @returns {Uint8Array}\n */\nfunction encodeWriteStatusRequest(param) {\n    // 检测：输入参数释放合法\n    testUserParam(param);\n\n    var pduEntity = newPduEntity();\n    pduEntity.func = 0x05;\n    pduEntity.devAddr = param.devAddr;\n\n    // 检测：是否有流水号参数\n    if (param.sn != undefined \u0026\u0026 param.sn != null) {\n        pduEntity.sn = param.sn;\n    }\n\n    // 检测：是否有流水号参数\n    if (param.value == undefined || param.value == null) {\n        throw new Error(\"实体字段为空：value\");\n    }\n\n    pduEntity.data = new Uint8Array(4);\n    pduEntity.data[0] = param.regAddr / 0x100;\n    pduEntity.data[1] = param.regAddr % 0x100;\n\n    if (param.value == true) {\n        pduEntity.data[2] = (0xff);\n        pduEntity.data[3] = (0x00);\n    } else {\n        pduEntity.data[2] = (0x00);\n        pduEntity.data[3] = (0x00);\n    }\n\n    return encodePdu(pduEntity, param.modbusMode);\n}\n\n/**\n * 解码写寄存器\n *\n * @param pdu\n * @param param\n * @returns {{status: *[]}}\n */\nfunction decodeWriteStatusRespond(pdu, param) {\n    // 报文解码\n    var pduEntity = decodePdu(pdu, param.modbusMode);\n\n\n    if (pduEntity.func == 0x80 \u0026\u0026 pduEntity.data.length \u003e 0) {\n        pduEntity.errCode = pduEntity.data[0];\n        pduEntity.errMsg = getError(pduEntity.data[0]);\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    // 检测是否为输入0x05的返回\n    if (pduEntity.func != 0x05) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    // 检测：数据长度\n    if (pduEntity.data.length != 4) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    var respond = {\n        status: false\n    };\n\n    respond.regAddr = (((pduEntity.data[0] \u0026 0xff) * 0x100) + (pduEntity.data[1] \u0026 0xff));\n    respond.status = ((pduEntity.data[2] \u0026 0xff) == 0xff);\n\n    return respond;\n}\n\n/**\n * 读寄存器编码器请求\n *\n * @param param\n * @returns {Uint8Array}\n */\nfunction encodeReadRegistersRequest(func, param) {\n    // 检测：输入参数释放合法\n    testUserParam(param);\n\n    var pduEntity = newPduEntity();\n    pduEntity.func = func;\n    pduEntity.devAddr = param.devAddr;\n\n    // 检测：是否有流水号参数\n    if (param.sn != undefined \u0026\u0026 param.sn != null) {\n        pduEntity.sn = param.sn;\n    }\n\n    pduEntity.data = new Uint8Array(4);\n    pduEntity.data[0] = param.regAddr / 0x100;\n    pduEntity.data[1] = param.regAddr % 0x100;\n    pduEntity.data[2] = param.regCnt / 0x100;\n    pduEntity.data[3] = param.regCnt % 0x100;\n\n    return encodePdu(pduEntity, param.modbusMode);\n}\n\n/**\n * 数据解析\n * @param pdu\n * @param param\n * @returns {{status: *[]}}\n */\nfunction decodeReadRegistersRespond(pdu, param) {\n    // 报文解码\n    var pduEntity = decodePdu(pdu, param.modbusMode);\n\n\n    if (pduEntity.func == 0x83 \u0026\u0026 pduEntity.data.length \u003e 0) {\n        pduEntity.errCode = pduEntity.data[0];\n        pduEntity.errMsg = getError(pduEntity.data[0]);\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    // 检测是否为输入03和04的返回\n    if (pduEntity.func != 0x03 \u0026\u0026 pduEntity.func != 0x04) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    // 检测：数据长度\n    if (pduEntity.data.length \u003c 1) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    if ((pduEntity.data[0] \u0026 0xff) != pduEntity.data.length - 1) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    if (pduEntity.data.length % 2 != 1) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    var statusList = [];\n\n    var wCount = (pduEntity.data.length - 1) / 2;\n    var byAt = 1;\n    for (var i = 0; i \u003c wCount; i++) {\n        var status = (pduEntity.data[byAt] \u0026 0xff) * 0x100;\n        status += pduEntity.data[byAt + 1] \u0026 0xFF;\n\n        statusList.push(status);\n        byAt += 2;\n    }\n\n    return statusList;\n}\n\n/**\n * 读状态编码器请求\n * @param func\n * @param param\n * @returns {Uint8Array}\n */\nfunction encodeReadStatusRequest(func, param) {\n    // 检测：输入参数释放合法\n    testUserParam(param);\n\n    var pduEntity = newPduEntity();\n    pduEntity.func = func;\n    pduEntity.devAddr = param.devAddr;\n\n    // 检测：是否有流水号参数\n    if (param.sn != undefined \u0026\u0026 param.sn != null) {\n        pduEntity.sn = param.sn;\n    }\n\n    pduEntity.data = new Uint8Array(4);\n    pduEntity.data[0] = param.regAddr / 0x100;\n    pduEntity.data[1] = param.regAddr % 0x100;\n    pduEntity.data[2] = param.regCnt / 0x100;\n    pduEntity.data[3] = param.regCnt % 0x100;\n\n    return encodePdu(pduEntity, param.modbusMode);\n}\n\n/**\n * 数据解析\n * @param pdu\n * @param param\n * @returns {{status: *[]}}\n */\nfunction decodeReadStatusRespond(pdu, param) {\n    // 报文解码\n    var pduEntity = decodePdu(pdu, param.modbusMode);\n\n\n    if (pduEntity.func == 0x80 \u0026\u0026 pduEntity.data.length \u003e 0) {\n        pduEntity.errCode = pduEntity.data[0];\n        pduEntity.errMsg = getError(pduEntity.data[0]);\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    // 检测是否为输入03和04的返回\n    if (pduEntity.func != 0x01 \u0026\u0026 pduEntity.func != 0x02) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    // 检测：数据长度\n    if (pduEntity.data.length \u003c 1) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    if ((pduEntity.data[0] \u0026 0xff) != pduEntity.data.length - 1) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    var wCount = pduEntity.data[0];\n    if ((wCount + 1) != pduEntity.data.length) {\n        throw new Error(\"返回的长度不正确\");\n    }\n\n    var status = []\n\n\n    var byStatus = 0;\n    for (var i = 1; i \u003c pduEntity.data.length; i++) {\n        var byAt = pduEntity.data[i];\n        var byBit = 0x01;\n\n        for (var k = 0; k \u003c 8; k++) {\n            status.push((byAt \u0026 byBit) != 0);\n\n            byBit \u003c\u003c= 1;\n        }\n    }\n\n    return status;\n}\n\n/**\n * 出错码信息\n *\n * @param errCode\n * @returns {string}\n */\nfunction getError(code) {\n    if (code == 1) {\n        return \"err=01:非法的功能码\";\n    }\n    if (code == 2) {\n        return \"err=02:非法的数据地址\";\n    }\n    if (code == 3) {\n        return \"err=03:非法的数据值\";\n    }\n    if (code == 4) {\n        return \"err=04:服务器故障\";\n    }\n    if (code == 5) {\n        return \"err=05:确认\";\n    }\n    if (code == 6) {\n        return \"err=06:服务器繁忙\";\n    }\n    if (code == 10) {\n        return \"err=10:网关故障:网关路经是无效的\";\n    }\n    if (code == 11) {\n        return \"err=11:网关故障:目标设备没有响应\";\n    }\n\n    return \"\";\n}\n\n/**\n * 构造PDU实体\n * 注意：使用时，data必须初始化一个具体的长度，中间不可变\n *\n * @param param\n * @returns {{devAddr: number, func: number, data: Uint8Array, errCode: number, errMsg: string, sn: number}}\n */\nfunction newPduEntity() {\n    var pduEntity = {\n        \"sn\": 0,// 流水号\n        \"devAddr\": 0x01,// 地址\n        \"func\": 0x03,// 功能码\n        \"errCode\": 0, // 出错信息\n        \"errMsg\": \"\", //  出错信息\n        \"data\": new Uint8Array(0)// 数据域\n    };\n\n    return pduEntity;\n}\n\n/**\n * 测试数据的合法性\n *\n * @param entity\n */\nfunction testPduEntity(entity) {\n    if (entity.sn == undefined || entity.sn == null) {\n        throw new Error(\"实体字段为空：sn\");\n    }\n    if (entity.devAddr == undefined || entity.devAddr == null) {\n        throw new Error(\"实体字段为空：devAddr\");\n    }\n    if (entity.func == undefined || entity.func == null) {\n        throw new Error(\"实体字段为空：func\");\n    }\n    if (entity.errCode == undefined || entity.errCode == null) {\n        throw new Error(\"实体字段为空：errCode\");\n    }\n    if (entity.errMsg == undefined || entity.errMsg == null) {\n        throw new Error(\"实体字段为空：errMsg\");\n    }\n    if (entity.data == undefined || entity.data == null) {\n        throw new Error(\"实体字段为空：data\");\n    }\n    if (entity.data.length == undefined || entity.data.length == null) {\n        throw new Error(\"实体字段为空：data.length\");\n    }\n}\n\n/**\n * 实例化一个用户输入参数\n * 说明：这是基本的用户输入参数，至少包含这些信息\n *\n * @returns {{devAddr: number, regCnt: number, modbusMode: string, regAddr: number}}\n */\nfunction newUserParam() {\n    var paramEntity = {\n        \"func\": 0x03,// 功能代码\n        \"devAddr\": 0x01,// 设备地址\n        \"regAddr\": 0x00,// 寄存器地址\n        \"regCnt\": 0x00, // 寄存器数量\n        \"modbusMode\": \"\" // ModBus模式\n    };\n\n    return paramEntity;\n}\n\n/**\n * 测试数据的合法性\n *\n * @param entity\n */\nfunction testUserParam(entity) {\n    if (entity.devAddr == undefined || entity.devAddr == null) {\n        throw new Error(\"实体字段为空：devAddr\");\n    }\n    if (entity.regAddr == undefined || entity.regAddr == null) {\n        throw new Error(\"实体字段为空：regAddr\");\n    }\n    if (entity.regCnt == undefined || entity.regCnt == null) {\n        throw new Error(\"实体字段为空：regCnt\");\n    }\n    if (entity.modbusMode == undefined || entity.modbusMode == null) {\n        throw new Error(\"实体字段为空：modbusMode\");\n    }\n}\n\n/**\n * 编码\n * @param entity modbus实体\n * @param mode 工作模式\n *\n * @returns {Uint8Array} 数据报文\n */\nfunction encodePdu(entity, mode) {\n    if (mode == undefined || mode == null) {\n        throw new Error(\"参数为空：mode\");\n    }\n\n    if (mode == \"RTU\") {\n        return encodeRtuPdu(entity);\n    }\n    if (mode == \"TCP\") {\n        return encodeTcpPdu(entity);\n    }\n\n    throw new Error(\"不支持的模式\" + mode);\n}\n\n/**\n * 解码函数\n *\n * @param pdu 报文\n * @param mode 工作模式\n * @returns {{devAddr: number, func: number, data: Uint8Array, errCode: number, errMsg: string, sn: number}|null}\n */\nfunction decodePdu(pdu, mode) {\n    if (mode == undefined || mode == null) {\n        throw new Error(\"参数为空：mode\");\n    }\n\n    if (mode == \"RTU\") {\n        return decodeRtuPdu(pdu);\n    }\n    if (mode == \"TCP\") {\n        return decodeTcpPdu(pdu);\n    }\n\n    throw new Error(\"不支持的模式\" + mode);\n}\n\n/**\n * 编码函数\n *\n * @param entity\n * @returns {Uint8Array}\n */\nfunction encodeRtuPdu(entity) {\n    // 检测：输入参数释放合法\n    testPduEntity(entity);\n\n    var data = new Uint8Array(entity.data.length + 4);\n\n    // Slave Address 11\n    // Function 01\n    // Starting Address Hi 00\n    // Starting Address Lo 13\n    // No. of Points Hi 00\n    // No. of Points Lo 25\n    // Error Check (LRC or CRC) ––\n\n    // 地址码\n    data[0] = entity.devAddr;\n\n    // 功能码\n    data[1] = entity.func;\n\n    // 数据域\n    arraycopy(entity.data, 0, data, 2, entity.data.length);\n\n    // 校验CRC\n    var crc16 = calculateCRC16(data, 0, data.length - 2, 0xFFFF, 0xA001);\n    data[data.length - 2] = crc16 % 0x100;\n    data[data.length - 1] = crc16 / 0x100;\n\n    return data;\n}\n\n/**\n * 解码器函数\n *\n * @param pdu\n * @returns {null|{devAddr: number, func: number, data: Uint8Array, errCode: number, errMsg: string, sn: number}}\n */\nfunction decodeRtuPdu(pdu) {\n    if (pdu == null || pdu == undefined || pdu.length \u003c 4) {\n        throw new Error(\"输入参数pdu异常\");\n    }\n\n    if (pdu.length \u003c 4) {\n        return null;\n    }\n\n    var entity = newPduEntity();\n\n    // 地址码\n    entity.devAddr = pdu[0];\n\n    // 功能码\n    entity.func = pdu[1];\n\n    // 数据域\n    entity.data = new Uint8Array(pdu.length - 4);\n    arraycopy(pdu, 2, entity.data, 0, pdu.length);\n\n    // 校验CRC\n    var crc16 = calculateCRC16(pdu, 0, pdu.length - 2, 0xFFFF, 0xA001);\n    var crcH = crc16 \u0026 0xff;\n    var crcL = (crc16 \u0026 0xff00) \u003e\u003e 8;\n    if (pdu[pdu.length - 1] == crcL \u0026\u0026 pdu[pdu.length - 2] == crcH) {\n        return entity;\n    }\n\n    throw new Error(\"输入参数pdu异常\");\n}\n\n/**\n * 编码函数\n *\n * @param entity\n * @returns {Uint8Array}\n */\nfunction encodeTcpPdu(entity) {\n    // 检测：输入参数释放合法\n    testPduEntity(entity);\n\n    var data = new Uint8Array(entity.data.length + 8);\n\n    // 流水号\n    data[0] = ((entity.sn \u0026 0xff00) \u003e\u003e 8);\n    data[1] = (entity.sn \u0026 0xff);\n\n    // 协议类型\n    data[2] = 0;\n    data[3] = 0;\n\n    // 报文长度\n    var len = entity.data.length + 2;\n    data[4] = (len \u0026 0xff00) \u003e\u003e 8;\n    data[5] = len \u0026 0xff;\n\n    //地址\n    data[6] = entity.devAddr;\n\n    // 功能\n    data[7] = entity.func;\n\n    //数据\n    arraycopy(entity.data, 0, data, 8, entity.data.length);\n\n    return data;\n}\n\n/**\n * 解码器函数\n *\n * @param pdu\n * @returns {null|{devAddr: number, func: number, data: Uint8Array, errCode: number, errMsg: string, sn: number}}\n */\nfunction decodeTcpPdu(pdu) {\n    if (pdu == null || pdu == undefined || pdu.length \u003c 4) {\n        throw new Error(\"输入参数pdu异常\");\n    }\n\n    var entity = new newPduEntity();\n\n    // 流水号\n    var wSn = (pdu[0] \u0026 0xff) * 0x100;\n    wSn += pdu[1] \u0026 0xff;\n    entity.sn = wSn \u0026 0xffff;\n\n    // 协议类型\n    if (pdu[2] != 0 || pdu[3] != 0) {\n        throw new Error(\"协议类型不合法\");\n    }\n\n    // 报文长度\n    var len = (pdu[4] \u0026 0xff) * 0x100;\n    len += pdu[5] \u0026 0xff;\n    if (pdu.length != len + 6) {\n        throw new Error(\"数据长度不匹配\");\n    }\n    if (len \u003c 2) {\n        throw new Error(\"数据长度不合法\");\n    }\n\n    //地址\n    entity.devAddr = pdu[6];\n\n    // 功能\n    entity.func = pdu[7];\n\n    //数据\n    entity.data = new Uint8Array(len - 2);\n    arraycopy(pdu, 8, entity.data, 0, entity.data.length);\n\n    return entity;\n}\n\n","main":"include"}}', '{"description":"Fox-Edge提供的常用Modbus的Core库。\n\n它的目的，是给开发者们，提供一个通用modbus的解码器框架，简化modbus解码器的处理"}', 'status', 'include', 1, 2000, 1732883941038, 1732883941038),
	(3, 'Read System Measures Table', 'CE+T UPS V3.0', '深圳安圣电气有限公司', 'JavaScript', 'device', '{"decode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction decode() {\n    var param = JSON.parse(fox_edge_param);\n    var result = decodeReadHoldingRegister(fox_edge_data, param);\n    return JSON.stringify(result);\n}\n\n/**\n * 解码数据\n *\n * @param hexRecv\n * @param param\n * @returns {{}}\n */\nfunction decodeReadHoldingRegister(hexRecv, param) {\n    // 检查输入参数\n    testEmpty(param[\"设备地址\"], \"输入参数不能为空: 设备地址\");\n\n    param.devAddr = param[\"设备地址\"]\n    param.regAddr = 0x42E\n    param.regCnt = 0x45\n    param.modbusMode = \"RTU\"\n\n\n    var pdu = hexToArray(hexRecv);\n\n    var arrStatus = decodeReadRegistersRespond(pdu, param)\n\n    //检查数据域长度:\n    if (arrStatus.length != 69) {\n        return null;\n    }\n\n    var value = {}\n\n    var index = 0;\n\n    value[\"系统输出电压\"] = arrStatus[index++];\n    value[\"系统输出电流\"] = arrStatus[index++] / 10;\n    value[\"系统输出功率\"] = arrStatus[index++];\n    value[\"系统输出频率\"] = arrStatus[index++] / 10;\n    value[\"负载比\"] = arrStatus[index++];\n    value[\"组1输入电压\"] = arrStatus[index++] / 10;\n    value[\"组2输入电压\"] = arrStatus[index++] / 10;\n    value[\"组3输入电压\"] =  arrStatus[index++] / 10;\n    value[\"组4输入电压\"] =  arrStatus[index++] / 10;\n\n    //=====================\n    //1079 spare\n    //=====================\n    index++;\n\n\n    //===================================================\n    //1080  Iout inverter 0\n    //1081  Pout inverter 0\n    //1082  dissipator temperature inverter 0\n    //……\n    //1125  Iout inverter 15\n    //1126  Pout inverter 15\n    //1127  dissipator temperature inverter 15\n    //===================================================\n    for (var i = 0; i \u003c 16; i++) {\n        var idx = padStart(\"\" + i + 1, 2, 0)\n        \n        value[\"逆变器\"+idx+\"输出电流\"] = arrStatus[index++] / 10;\n        value[\"逆变器\"+idx+\"输出功率\"] = arrStatus[index++];\n        value[\"逆变器\"+idx+\"温度\"] = arrStatus[index++];\n    }\n\n\n    return value;\n}\n","main":"decode"},"encode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction encode() {\n    var param = JSON.parse(fox_edge_param);\n    return encodeReadHoldingRegister(param);\n}\n\n/**\n * 数据编码\n *\n * @param param\n * @returns {string}\n */\nfunction encodeReadHoldingRegister(param) {\n    // 检查输入参数\n    testEmpty(param[\"设备地址\"], \"输入参数不能为空: 设备地址\");\n\n    param.devAddr = param[\"设备地址\"]\n    param.regAddr = 0x42E\n    param.regCnt = 0x45\n    param.modbusMode = \"RTU\"\n\n\n    var pdu = encodeReadRegistersRequest(0x03, param);\n    return arrayToHex(pdu);\n}","main":"encode"}}', '{"description":""}', 'status', 'exchange', 1, 2000, 1732883941050, 1732883941050),
	(4, 'Read Alarms And Events Table', 'CE+T UPS V3.0', '深圳安圣电气有限公司', 'JavaScript', 'device', '{"decode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction decode() {\n    var param = JSON.parse(fox_edge_param);\n    var result = decodeReadHoldingRegister(fox_edge_data, param);\n    return JSON.stringify(result);\n}\n\n/**\n * 解码数据\n *\n * @param hexRecv\n * @param param\n * @returns {{}}\n */\nfunction decodeReadHoldingRegister(hexRecv, param) {\n    // 检查输入参数\n    testEmpty(param[\"设备地址\"], \"输入参数不能为空: 设备地址\");\n\n    param.devAddr = param[\"设备地址\"]\n    param.regAddr = 0x41F\n    param.regCnt = 0x07\n    param.modbusMode = \"RTU\"\n\n\n    var pdu = hexToArray(hexRecv);\n\n    var arrStatus = decodeReadRegistersRespond(pdu, param)\n\n    //检查数据域长度:\n    if (arrStatus.length != 7) {\n        return null;\n    }\n\n    var value = {}\n\n    var index = 0;\n\n    value[\"48V直流熔丝断告警状态\"] = ((arrStatus[index]) \u0026 0x02) == 0x02;\n    value[\"用户交流熔丝断告警状态\"] = ((arrStatus[index]) \u0026 0x04) == 0x04;\n    value[\"辅助交流熔丝断告警状态\"] = ((arrStatus[index]) \u0026 0x08) == 0x08;\n    value[\"直流电压超限告警状态\"] = ((arrStatus[index]) \u0026 0x10) == 0x10;\n    value[\"输出电压超限告警状态\"] = ((arrStatus[index]) \u0026 0x40) == 0x40;\n    value[\"逆变器故障告警状态\"] = ((arrStatus[index]) \u0026 0x0300) != 0x00;\n    value[\"是否有逆变器手动停\"] = ((arrStatus[index]) \u0026 0x0800) != 0x00;\n    value[\"不同步告警状态\"] = ((arrStatus[index]) \u0026 0x1000) != 0x00;\n    value[\"系统紧急告警状态\"] = ((arrStatus[index]) \u0026 0x4000) != 0x00;\n    value[\"系统非紧急告警状态\"] = ((arrStatus[index]) \u0026 0x8000) != 0x00;\n\n    index++;\n\n\n    //================================================\n    //1056\n    //================================================\n\n    value[\"逆变器限流告警状态\"] = ((arrStatus[index]) \u0026 0x0001) != 0x00;\n    value[\"逆变器超温告警状态\"] = ((arrStatus[index]) \u0026 0x0008) != 0x00;\n\n    index++;\n\n    //==========================================\n    //1057\n    //==========================================\n\n\n    var wValue = 0x01;\n    for (var i = 0; i \u003c 16; i++) {\n        var key = \"逆变器\" + padStart(\"\" + i, 2, 0) + \"传输故障告警状态\"\n        value[key] = ((arrStatus[index]) \u0026 wValue) != 0x00;\n\n        wValue = wValue \u003c\u003c 1;\n    }\n\n    index++;\n\n    //=====================================\n    //1058\n    //======================================\n    index++;\n\n    //=====================================\n    //1059\n    //======================================\n    index++;\n\n    //=====================================\n    //1060\n    //===================================\n\n    value[\"过载告警状态\"] = ((arrStatus[index]) \u0026 0x0004) != 0x00;\n    value[\"是否工作在在线方式\"] = ((arrStatus[index]) \u0026 0x0020) != 0x00;\n    value[\"是否工作在逆变方式\"] = ((arrStatus[index]) \u0026 0x0040) != 0x00;\n    value[\"是否工作在交流方式\"] = ((arrStatus[index]) \u0026 0x0080) != 0x00;\n    value[\"负载是否由逆变器供电\"] = ((arrStatus[index]) \u0026 0x0100) != 0x00;\n    value[\"负载是否由市电供电\"] = ((arrStatus[index]) \u0026 0x0200) != 0x00;\n    value[\"是否由逆变切换到手动旁路\"] = ((arrStatus[index]) \u0026 0x1000) != 0x00;\n    value[\"是否由市电切换到手动旁路\"] = ((arrStatus[index]) \u0026 0x2000) != 0x00;\n\n    return value;\n}\n","main":"decode"},"encode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction encode() {\n    var param = JSON.parse(fox_edge_param);\n    return encodeReadHoldingRegister(param);\n}\n\n/**\n * 数据编码\n *\n * @param param\n * @returns {string}\n */\nfunction encodeReadHoldingRegister(param) {\n    // 检查输入参数\n    testEmpty(param[\"设备地址\"], \"输入参数不能为空: 设备地址\");\n\n    param.devAddr = param[\"设备地址\"]\n    param.regAddr = 0x41F\n    param.regCnt = 0x07\n    param.modbusMode = \"RTU\"\n\n\n    var pdu = encodeReadRegistersRequest(0x03, param);\n    return arrayToHex(pdu);\n}","main":"encode"}}', '{"description":""}', 'status', 'exchange', 1, 2000, 1732883941063, 1732883941063),
	(5, 'modbusModelLibs', 'MODBUS', '广州灵狐技术有限公司', 'JavaScript', 'device', '{"include":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n\n/**\n * 验证设备模型是否正确\n *\n * @param deviceModel\n * @returns {boolean}\n */\nfunction verifyDeviceModel4Registers(deviceModel) {\n    if (deviceModel.value_name == undefined || deviceModel.value_name == null) {\n        return false;\n    }\n    if (deviceModel.value_type == undefined || deviceModel.value_type == null) {\n        return false;\n    }\n    if (deviceModel.value_index == undefined || deviceModel.value_index == null) {\n        return false;\n    }\n    if (deviceModel.bit_index == undefined || deviceModel.bit_index == null) {\n        return false;\n    }\n    if (deviceModel.bit_length == undefined || deviceModel.bit_length == null) {\n        return false;\n    }\n    if (deviceModel.magnification == undefined || deviceModel.magnification == null) {\n        return false;\n    }\n\n    return true;\n}\n\n/**\n * 查找是否存在该模型项目\n *\n * @param modelList\n * @param objectName\n * @returns {null|*}\n */\nfunction findDeviceModel(modelList, objectName) {\n    if (objectName == undefined || objectName == null) {\n        return null;\n    }\n\n    for (var modelIndex = 0; modelIndex \u003c modelList.length; modelIndex++) {\n        if (modelList[modelIndex].value_name == objectName) {\n            return modelList[modelIndex]\n        }\n    }\n\n    return null;\n}\n\n/**\n * 编码函数：使用设备模型，编码寄存器的内容\n *\n * @param modelList 引用的设备模型\n * @param objectName 待编码的对象名称\n * @param objectValue 待编码的对象的数值\n * @returns {*}\n */\nfunction encodeRegistersValue(modelList, objectName, objectValue) {\n    // 获得对应的数据模型\n    var jDecoderValueParam = findDeviceModel(modelList, objectName);\n    if (jDecoderValueParam == null) {\n        throw new Error(\"未定义该对象的信息：\" + objectName);\n    }\n\n\n    // 数据类型的转换\n    jDecoderValueParam.magnification = parseFloat(jDecoderValueParam.magnification);\n    jDecoderValueParam.value_index = parseInt(jDecoderValueParam.value_index, 10);\n\n    var result = {};\n    if (jDecoderValueParam.value_type == \"int\") {\n        result.regAddr = jDecoderValueParam.value_index;\n        result.regCnt = 1;\n        result.value = parseInt(objectValue, 10) / jDecoderValueParam.magnification;\n        return result;\n    }\n    if (jDecoderValueParam.value_type == \"long\") {\n        result.regAddr = jDecoderValueParam.value_index;\n        result.regCnt = 2;\n\n        var value = parseInt(objectValue, 10) / jDecoderValueParam.magnification;\n        result.value = new Uint8Array(4);\n        result.value[0] = value / 0x10000 / 0x100;\n        result.value[1] = value / 0x10000 % 0x100;\n        result.value[2] = value % 0x10000 / 0x100;\n        result.value[3] = value % 0x10000 % 0x100;\n        return result;\n    }\n    if (jDecoderValueParam.value_type == \"float\") {\n        result.regAddr = jDecoderValueParam.value_index;\n        result.regCnt = 1;\n        result.value = parseInt(objectValue, 10) / jDecoderValueParam.magnification;\n        return result;\n    }\n    if (jDecoderValueParam.value_type == \"enum\") {\n        // 分拆枚举定义：类似格式{0xAA=开机}{0x55=关机}\n        var list = splitEnumList(jDecoderValueParam.determine);\n\n        // 编码枚举值\n        var item = encodeEnum(objectValue, list);\n        if (item.name == undefined || item.name == null || item.name === '''') {\n            throw new Error(\"不支持对该数据进行编码 \" + objectName);\n        }\n\n        result.regAddr = jDecoderValueParam.value_index;\n        result.regCnt = 1;\n        result.value = item.value;\n        return result;\n    }\n\n    throw new Error(\"不支持对该数据进行编码 \" + objectName);\n}\n\n/**\n * 解码函数：使用设备模型，编码寄存器的内容\n *\n * @param modelList\n * @param address\n * @param count\n * @param statusList\n * @returns {{}}\n */\nfunction decodeRegistersValue(modelList, address, count, statusList) {\n    var offsetStart = address;\n    var offsetEnd = address + count - 1;\n\n    var result = {};\n\n    for (var modelIndex = 0; modelIndex \u003c modelList.length; modelIndex++) {\n        var jDecoderValueParam = modelList[modelIndex];\n        var name = jDecoderValueParam.value_name;\n\n        // 验证数据\n        if (!verifyDeviceModel4Registers(jDecoderValueParam)) {\n            continue;\n        }\n\n        // 类型转换\n        jDecoderValueParam.magnification = parseFloat(jDecoderValueParam.magnification);\n        jDecoderValueParam.value_index = parseInt(jDecoderValueParam.value_index, 10);\n        jDecoderValueParam.bit_length = parseInt(jDecoderValueParam.bit_length, 10);\n        jDecoderValueParam.bit_index = parseInt(jDecoderValueParam.bit_index, 10);\n\n        if (jDecoderValueParam.value_index \u003c offsetStart) {\n            continue;\n        }\n        if (jDecoderValueParam.value_index \u003e offsetEnd + 1) {\n            continue;\n        }\n\n        var index = jDecoderValueParam.value_index - offsetStart;\n        if (index \u003e= statusList.length) {\n            continue;\n        }\n\n        var status = statusList[index];\n\n\n        // 整数：比如284，编码格式为int16，但实际上是放大10倍，变为2840\n        if (jDecoderValueParam.value_type == \"int\") {\n            result[name] = status * jDecoderValueParam.magnification;\n            continue;\n        }\n        // 整数：比如284，编码格式为long32，但实际上是放大10倍，变为2840\n        if (jDecoderValueParam.value_type == \"long\") {\n            if (statusList.length \u003c= index + 1) {\n                continue;\n            }\n\n            status = statusList[index] * 0x10000 + statusList[index + 1];\n\n            result[name] = status * jDecoderValueParam.magnification;\n            continue;\n        }\n        // 定点小数：比如284，编码格式为int16，但实际上是缩小10倍，变为实28.4\n        if (jDecoderValueParam.value_type == \"fix-float\") {\n            result[name] = status * jDecoderValueParam.magnification;\n            continue;\n        }\n        // 浮点数\n        if (jDecoderValueParam.value_type == \"float\") {\n            if (jDecoderValueParam.bit_length == 32) {\n                // 32位浮点（数默认格式：低位在前，高位在后）：例如，45 0f 60 00 数值位2294.0\n                var bit0 = statusList[index + 1] \u003e\u003e 0 \u0026 0xff;\n                var bit1 = statusList[index + 1] \u003e\u003e 8 \u0026 0xff;\n                var bit2 = statusList[index + 0] \u003e\u003e 0 \u0026 0xff;\n                var bit3 = statusList[index + 0] \u003e\u003e 8 \u0026 0xff;\n                var fValue = bitsToFloat(bit0, bit1, bit2, bit3);\n                result[name] = fValue * jDecoderValueParam.magnification;\n            }\n            continue;\n        }\n        if (jDecoderValueParam.value_type == \"bool\") {\n            var value = 0;\n            for (var i = 0; i \u003c jDecoderValueParam.bit_length; i++) {\n                value += status \u0026 binary(jDecoderValueParam.bit_index + i);\n            }\n\n            if (jDecoderValueParam.determine == \"\u003e0\") {\n                result[name] = value \u003e 0;\n            } else {\n                result[name] = value == 0;\n            }\n\n        }\n        // 枚举\n        if (jDecoderValueParam.value_type == \"enum\") {\n            // 分拆枚举定义：类似格式{0xAA=开机}{0x55=关机}\n            var list = splitEnumList(jDecoderValueParam.determine);\n\n            // 解码枚举值\n            var item = decodeEnum(status, list);\n            if (item.name == undefined || item.name == null || item.name === '''') {\n                continue;\n            }\n\n            result[name] = item.name;\n        }\n\n    }\n\n    return result;\n}\n\n/**\n * 编码枚举值\n *\n * @param status\n * @param enumList\n * @returns {*}\n */\nfunction encodeEnum(value, enumList) {\n    for (var i = 0; i \u003c enumList.length; i++) {\n        var item = enumList[i];\n        if (item.name == value) {\n            return item;\n        }\n    }\n\n    return {name: ''未定义：'' + status}\n}\n\n/**\n * 解码枚举值\n *\n * @param status\n * @param enumList\n * @returns {*}\n */\nfunction decodeEnum(status, enumList) {\n    for (var i = 0; i \u003c enumList.length; i++) {\n        var item = enumList[i];\n        if (item.value == status) {\n            return item;\n        }\n    }\n\n    return {name: ''未定义：'' + status}\n}\n\n/**\n * 分拆格式：\n * 例如，{0xAA=开机}{0x55=关机}\n *\n * @param enums\n * @returns {*[]}\n */\nfunction splitEnumList(enums) {\n    if (enums == undefined || enums == null) {\n        return [];\n    }\n\n    var start = 0;\n    var end = 0;\n    var list = [];\n    while (true) {\n        start = enums.indexOf(\"{\", start);\n        end = enums.indexOf(\"}\", start + 1);\n        if (start \u003c 0 || end \u003c 0) {\n            break;\n        }\n\n        var items = enums.substring(start + 1, end).split(\"=\");\n        if (items.length != 2) {\n            break;\n        } else {\n            start = end + 1;\n        }\n\n\n        var value = items[0].toLowerCase();\n\n        if (value.startsWith(\"0x\")) {\n            value = parseInt(value.substring(2, value.length), 16);\n        } else {\n            value = parseInt(value, 10);\n        }\n\n        var obj = {\n            value: value, name: items[1],\n        }\n        list.push(obj);\n    }\n\n    return list;\n}\n\n/**\n * 验证设备模型是否正确\n *\n * @param deviceModel\n * @returns {boolean}\n */\nfunction verifyDeviceModel4Status(deviceModel) {\n    if (deviceModel.value_name == undefined || deviceModel.value_name == null) {\n        return false;\n    }\n    if (deviceModel.value_index == undefined || deviceModel.value_index == null) {\n        return false;\n    }\n\n    return true;\n}\n\n/**\n * 数据编码\n *\n * @param modelList\n * @param objectName\n * @param objectValue\n * @returns {{}}\n */\nfunction encodeStatusValue(modelList, objectName, objectValue) {\n    // 获得对应的数据模型\n    var jDecoderValueParam = findDeviceModel(modelList, objectName);\n    if (jDecoderValueParam == null) {\n        throw new Error(\"未定义该对象的信息：\" + objectName);\n    }\n\n\n    // 数据类型的转换\n    jDecoderValueParam.value_index = parseInt(jDecoderValueParam.value_index, 10);\n\n    var result = {};\n    result.regAddr = jDecoderValueParam.value_index;\n    result.value = (true == objectValue);\n\n    return result;\n}\n\n/**\n * 解码函数：使用设备模型，编码寄存器的内容\n *\n * @param modelList\n * @param address\n * @param count\n * @param statusList\n * @returns {{}}\n */\nfunction decodeStatusValue(modelList, address, count, statusList) {\n    var offsetStart = address;\n    var offsetEnd = address + count - 1;\n\n    var result = {};\n\n    for (var modelIndex = 0; modelIndex \u003c modelList.length; modelIndex++) {\n        var jDecoderValueParam = modelList[modelIndex];\n        var name = jDecoderValueParam.value_name;\n\n        // 验证数据\n        if (!verifyDeviceModel4Status(jDecoderValueParam)) {\n            continue;\n        }\n\n        // 类型转换\n        jDecoderValueParam.value_index = parseInt(jDecoderValueParam.value_index, 10);\n\n        if (jDecoderValueParam.value_index \u003c offsetStart) {\n            continue;\n        }\n        if (jDecoderValueParam.value_index \u003e offsetEnd + 1) {\n            continue;\n        }\n\n        var index = jDecoderValueParam.value_index - offsetStart;\n        if (index \u003e= statusList.length) {\n            continue;\n        }\n\n        var status = statusList[index];\n        result[name] = status;\n    }\n\n    return result;\n}\n\n/**\n * 2位置进制转数字，比如0=0x01，1=0x02，2=0x04，3=0x08，4=0x10\n *\n * @param pos 位置\n * @return 值\n */\nfunction binary(pos) {\n    value = 1;\n    while (pos-- \u003e= 0) {\n        value *= 2;\n    }\n\n    return value / 2;\n}","main":"include"}}', '{"description":"Fox-Edge提供的常用Modbus的模型库。\n\n它的目的，是给开发者们，提供一个支持模板的通用modbus的解码器框架，简化modbus解码器的处理\n\n相关线上工具：\nhttps://wejson.cn/csv2json/"}', 'status', 'include', 1, 2000, 1744608027125, 1744608027125),
	(6, 'Read Coil Status', 'MODBUS', '广州灵狐技术有限公司', 'JavaScript', 'device', '{"decode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction decode() {\n    var param = JSON.parse(fox_edge_param);\n    var  result = decodeReadCoilStatusRespond(fox_edge_data, param);\n    return JSON.stringify(result);\n}\n\n/**\n * 解码数据\n *\n * @param hexRecv\n * @param param\n * @returns {{}}\n */\nfunction decodeReadCoilStatusRespond(hexRecv, param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.regAddr, \"输入参数不能为空: regAddr\");\n    testEmpty(param.regCnt, \"输入参数不能为空: regCnt\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    // 取出对应的设备模型\n    var modelList = fox_edge_model[param.modelName];\n    if (modelList == undefined || modelList == null) {\n        throw new Error(\"找不到对应的设备模型: \" + param.modelName);\n    }\n\n    var pdu = hexToArray(hexRecv);\n\n    var statusList = decodeReadStatusRespond(pdu, param);\n\n    var result = decodeStatusValue(modelList, param.regAddr, param.regCnt, statusList);\n    return result;\n}","main":"decode"},"encode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction encode() {\n  var param = JSON.parse(fox_edge_param);\n  return encodeReadCoilStatusRequest(param);\n}\n\n/**\n * 数据编码\n *\n * @param param\n * @returns {string}\n */\nfunction encodeReadCoilStatusRequest(param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.regAddr, \"输入参数不能为空: regAddr\");\n    testEmpty(param.regCnt, \"输入参数不能为空: regCnt\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    var pdu = encodeReadStatusRequest(0x01, param);\n    return arrayToHex(pdu);\n}","main":"encode"},"modelName":"modelName"}', '{"description":"说明：读取线圈状态命令（0x01）\n\n--------------------------------------------------------------------------------------------------------------------------\n\n设备参数范例：\n{\n     \"devAddr\": 50,\n     \"modelName\": \"正泰集团股份有限公司|三相电表(DT-SU666)|寄存器定义表\",\n     \"modbusMode\": \"RTU\"\n}\n\n输入参数范例：\n{\n     \"regCnt\": 10,\n     \"regAddr\": 4146\n}\n"}', 'status', 'exchange', 1, 2000, 1744608027131, 1744608027131),
	(7, 'Write Single Register', 'MODBUS', '广州灵狐技术有限公司', 'JavaScript', 'device', '{"decode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction decode() {\n    var param = JSON.parse(fox_edge_param);\n    var  result = decodeWriteSingleRegisterRespond(fox_edge_data, param);\n    return JSON.stringify(result);\n}\n\n/**\n * 解码数据\n *\n * @param hexRecv\n * @param param\n * @returns {{}}\n */\nfunction decodeWriteSingleRegisterRespond(hexRecv, param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.objectName, \"输入参数不能为空: objectName\");\n    testEmpty(param.objectValue, \"输入参数不能为空: objectValue\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    // 取出对应的设备模型\n    var modelList = fox_edge_model[param.modelName];\n    if (modelList == undefined || modelList == null) {\n        throw new Error(\"找不到对应的设备模型: \" + param.modelName);\n    }\n\n    var pdu = hexToArray(hexRecv);\n\n    var respond = decodeWriteRegistersRespond(pdu, param);\n    var result = {\n        regAddr: respond.regAddr\n    };\n    return result;\n}","main":"decode"},"encode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction encode() {\n  var param = JSON.parse(fox_edge_param);\n  return encodeWriteSingleRegisterRequest(param);\n}\n\n/**\n * 数据编码\n *\n * @param param\n * @returns {string}\n */\nfunction encodeWriteSingleRegisterRequest(param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.objectName, \"输入参数不能为空: objectName\");\n    testEmpty(param.objectValue, \"输入参数不能为空: objectValue\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    // 取出对应的设备模型\n    var modelList = fox_edge_model[param.modelName];\n    if (modelList == undefined || modelList == null) {\n        throw new Error(\"找不到对应的设备模型: \" + param.modelName);\n    }\n\n    // 计算地址信息\n    var regPar = encodeRegistersValue(modelList, param.objectName, param.objectValue)\n\n    // 填入地址信息\n    var usrPar = param;\n    usrPar.value = regPar.value;\n    usrPar.regAddr = regPar.regAddr;\n    usrPar.regCnt = regPar.regCnt;\n\n    var pdu = encodeWriteRegistersRequest(usrPar);\n    return arrayToHex(pdu);\n}","main":"encode"},"modelName":"modelName"}', '{"description":"说明：读取线圈状态命令（0x06）\n\n--------------------------------------------------------------------------------------------------------------------------\n\n设备参数范例：\n{\n     \"devAddr\": 50,\n     \"modelName\": \"正泰集团股份有限公司|三相电表(DT-SU666)|寄存器定义表\",\n     \"modbusMode\": \"RTU\"\n}\n\n输入参数范例：\n{\n     \"objectName\": “(当前)第一象限无功费率1电能”,\n     \"objectValue\": 3.137\n}\n"}', 'result', 'exchange', 1, 2000, 1744608027136, 1744608027136),
	(8, 'Read Input Register', 'MODBUS', '广州灵狐技术有限公司', 'JavaScript', 'device', '{"decode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction decode() {\n    var param = JSON.parse(fox_edge_param);\n    var  result = decodeReadInputRegisterRespond(fox_edge_data, param);\n    return JSON.stringify(result);\n}\n\n/**\n * 解码数据\n *\n * @param hexRecv\n * @param param\n * @returns {{}}\n */\nfunction decodeReadInputRegisterRespond(hexRecv, param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.regAddr, \"输入参数不能为空: regAddr\");\n    testEmpty(param.regCnt, \"输入参数不能为空: regCnt\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    // 取出对应的设备模型\n    var modelList = fox_edge_model[param.modelName];\n    if (modelList == undefined || modelList == null) {\n        throw new Error(\"找不到对应的设备模型: \" + param.modelName);\n    }\n\n    var pdu = hexToArray(hexRecv);\n\n    var statusList = decodeReadRegistersRespond(pdu, param);\n\n    var result = decodeRegistersValue(modelList, param.regAddr, param.regCnt, statusList);\n    return result;\n}","main":"decode"},"encode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction encode() {\n  var param = JSON.parse(fox_edge_param);\n  return encodeReadInputRegisterRequest(param);\n}\n\n/**\n * 数据编码\n *\n * @param param\n * @returns {string}\n */\nfunction encodeReadInputRegisterRequest(param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.regAddr, \"输入参数不能为空: regAddr\");\n    testEmpty(param.regCnt, \"输入参数不能为空: regCnt\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    var pdu = encodeReadRegistersRequest(0x04, param);\n    return arrayToHex(pdu);\n}\n","main":"encode"},"modelName":"modelName"}', '{"description":"说明：读取输入寄存器命令（0x04）\n\n--------------------------------------------------------------------------------------------------------------------------\n\n设备参数范例：\n{\n     \"devAddr\": 50,\n     \"modelName\": \"正泰集团股份有限公司|三相电表(DT-SU666)|寄存器定义表\",\n     \"modbusMode\": \"RTU\"\n}\n\n输入参数范例：\n{\n     \"regCnt\": 10,\n     \"regAddr\": 4146\n}\n"}', 'status', 'exchange', 1, 2000, 1744608027142, 1744608027142),
	(9, 'Write Multiple Register', 'MODBUS', '广州灵狐技术有限公司', 'JavaScript', 'device', '{"decode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction decode() {\n    var param = JSON.parse(fox_edge_param);\n    var  result = decodeWriteMultiRegisterRespond(fox_edge_data, param);\n    return JSON.stringify(result);\n}\n\n/**\n * 解码数据\n *\n * @param hexRecv\n * @param param\n * @returns {{}}\n */\nfunction decodeWriteMultiRegisterRespond(hexRecv, param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.objectName, \"输入参数不能为空: objectName\");\n    testEmpty(param.objectValue, \"输入参数不能为空: objectValue\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    // 取出对应的设备模型\n    var modelList = fox_edge_model[param.modelName];\n    if (modelList == undefined || modelList == null) {\n        throw new Error(\"找不到对应的设备模型: \" + param.modelName);\n    }\n\n    var pdu = hexToArray(hexRecv);\n\n    var respond = decodeWriteRegistersRespond(pdu, param);\n    var result = {\n        regAddr: respond.regAddr\n    };\n    return result;\n}\n","main":"decode"},"encode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction encode() {\n  var param = JSON.parse(fox_edge_param);\n  return encodeWriteMultiRegisterRequest(param);\n}\n\n/**\n * 数据编码\n *\n * @param param\n * @returns {string}\n */\nfunction encodeWriteMultiRegisterRequest(param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.objectName, \"输入参数不能为空: objectName\");\n    testEmpty(param.objectValue, \"输入参数不能为空: objectValue\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    // 取出对应的设备模型\n    var modelList = fox_edge_model[param.modelName];\n    if (modelList == undefined || modelList == null) {\n        throw new Error(\"找不到对应的设备模型: \" + param.modelName);\n    }\n\n    // 计算地址信息\n    var regPar = encodeRegistersValue(modelList, param.objectName, param.objectValue)\n\n    // 填入地址信息\n    var usrPar = param;\n    usrPar.value = regPar.value;\n    usrPar.regAddr = regPar.regAddr;\n    usrPar.regCnt = regPar.regCnt;\n\n    var pdu = encodeWriteRegistersRequest(usrPar);\n    return arrayToHex(pdu);\n}","main":"encode"},"modelName":"modelName"}', '{"description":""}', 'result', 'exchange', 1, 2000, 1744608027147, 1744608027147),
	(10, 'modbusCoreLibs', 'MODBUS', '广州灵狐技术有限公司', 'JavaScript', 'device', '{"include":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n\n\n/**\n * 写寄存器编码器请求\n *\n * @param param\n * @returns {Uint8Array}\n */\nfunction encodeWriteRegistersRequest(param) {\n    // 检测：输入参数释放合法\n    testUserParam(param);\n\n    var pduEntity = newPduEntity();\n    pduEntity.func = 0x06;\n    pduEntity.devAddr = param.devAddr;\n\n    // 检测：是否有流水号参数\n    if (param.sn != undefined \u0026\u0026 param.sn != null) {\n        pduEntity.sn = param.sn;\n    }\n\n    // 检测：是否有流水号参数\n    if (param.value == undefined || param.value == null) {\n        throw new Error(\"实体字段为空：value\");\n    }\n\n    if (param.regCnt == 1) {\n        // 设置单个寄存器\n        pduEntity.func = 0x06;\n        pduEntity.data = new Uint8Array(4);\n        // 寄存器起始地址\n        pduEntity.data[0] = param.regAddr / 0x100;\n        pduEntity.data[1] = param.regAddr % 0x100;\n        // 单个寄存器\n        pduEntity.data[2] = param.value / 0x100;\n        pduEntity.data[3] = param.value % 0x100;\n    }\n    if (param.regCnt \u003e 1) {\n        // 设置多个寄存器\n        pduEntity.func = 0x10;\n        pduEntity.data = new Uint8Array(5 + param.regCnt * 2);\n        // 寄存器起始地址\n        pduEntity.data[0] = param.regAddr / 0x100;\n        pduEntity.data[1] = param.regAddr % 0x100;\n        // 寄存器数量\n        pduEntity.data[2] = param.regCnt / 0x100;\n        pduEntity.data[3] = param.regCnt % 0x100;\n        // 寄存器数据的长度\n        pduEntity.data[4] = param.regCnt * 2;\n        // 连续寄存器的内容\n        for (var index = 0; index \u003c param.regCnt; index++) {\n            pduEntity.data[5 + index * 2] = param.value[0 + index * 2];\n            pduEntity.data[6 + index * 2] = param.value[1 + index * 2];\n        }\n    }\n\n    return encodePdu(pduEntity, param.modbusMode);\n}\n\n/**\n * 解码写寄存器\n *\n * @param pdu\n * @param param\n * @returns {{status: *[]}}\n */\nfunction decodeWriteRegistersRespond(pdu, param) {\n    // 报文解码\n    var pduEntity = decodePdu(pdu, param.modbusMode);\n\n\n    if (pduEntity.func == 0x86 \u0026\u0026 pduEntity.data.length \u003e 0) {\n        pduEntity.errCode = pduEntity.data[0];\n        pduEntity.errMsg = getError(pduEntity.data[0]);\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    // 检测是否为输入0x06的返回\n    if (pduEntity.func != 0x06 \u0026\u0026 pduEntity.func != 0x10) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    // 检测：数据长度\n    if (pduEntity.data.length != 4) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    var respond = {\n        value: 0\n    };\n\n    respond.regAddr = (((pduEntity.data[0] \u0026 0xff) * 0x100) + (pduEntity.data[1] \u0026 0xff));\n    respond.value = (((pduEntity.data[2] \u0026 0xff) * 0x100) + (pduEntity.data[3] \u0026 0xff));\n\n    return respond;\n}\n\n/**\n * 写寄存器编码器请求\n *\n * @param param\n * @returns {Uint8Array}\n */\nfunction encodeWriteStatusRequest(param) {\n    // 检测：输入参数释放合法\n    testUserParam(param);\n\n    var pduEntity = newPduEntity();\n    pduEntity.func = 0x05;\n    pduEntity.devAddr = param.devAddr;\n\n    // 检测：是否有流水号参数\n    if (param.sn != undefined \u0026\u0026 param.sn != null) {\n        pduEntity.sn = param.sn;\n    }\n\n    // 检测：是否有流水号参数\n    if (param.value == undefined || param.value == null) {\n        throw new Error(\"实体字段为空：value\");\n    }\n\n    pduEntity.data = new Uint8Array(4);\n    pduEntity.data[0] = param.regAddr / 0x100;\n    pduEntity.data[1] = param.regAddr % 0x100;\n\n    if (param.value == true) {\n        pduEntity.data[2] = (0xff);\n        pduEntity.data[3] = (0x00);\n    } else {\n        pduEntity.data[2] = (0x00);\n        pduEntity.data[3] = (0x00);\n    }\n\n    return encodePdu(pduEntity, param.modbusMode);\n}\n\n/**\n * 解码写寄存器\n *\n * @param pdu\n * @param param\n * @returns {{status: *[]}}\n */\nfunction decodeWriteStatusRespond(pdu, param) {\n    // 报文解码\n    var pduEntity = decodePdu(pdu, param.modbusMode);\n\n\n    if (pduEntity.func == 0x80 \u0026\u0026 pduEntity.data.length \u003e 0) {\n        pduEntity.errCode = pduEntity.data[0];\n        pduEntity.errMsg = getError(pduEntity.data[0]);\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    // 检测是否为输入0x05的返回\n    if (pduEntity.func != 0x05) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    // 检测：数据长度\n    if (pduEntity.data.length != 4) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    var respond = {\n        status: false\n    };\n\n    respond.regAddr = (((pduEntity.data[0] \u0026 0xff) * 0x100) + (pduEntity.data[1] \u0026 0xff));\n    respond.status = ((pduEntity.data[2] \u0026 0xff) == 0xff);\n\n    return respond;\n}\n\n/**\n * 读寄存器编码器请求\n *\n * @param param\n * @returns {Uint8Array}\n */\nfunction encodeReadRegistersRequest(func, param) {\n    // 检测：输入参数释放合法\n    testUserParam(param);\n\n    var pduEntity = newPduEntity();\n    pduEntity.func = func;\n    pduEntity.devAddr = param.devAddr;\n\n    // 检测：是否有流水号参数\n    if (param.sn != undefined \u0026\u0026 param.sn != null) {\n        pduEntity.sn = param.sn;\n    }\n\n    pduEntity.data = new Uint8Array(4);\n    pduEntity.data[0] = param.regAddr / 0x100;\n    pduEntity.data[1] = param.regAddr % 0x100;\n    pduEntity.data[2] = param.regCnt / 0x100;\n    pduEntity.data[3] = param.regCnt % 0x100;\n\n    return encodePdu(pduEntity, param.modbusMode);\n}\n\n/**\n * 数据解析\n * @param pdu\n * @param param\n * @returns {{status: *[]}}\n */\nfunction decodeReadRegistersRespond(pdu, param) {\n    // 报文解码\n    var pduEntity = decodePdu(pdu, param.modbusMode);\n\n\n    if (pduEntity.func == 0x83 \u0026\u0026 pduEntity.data.length \u003e 0) {\n        pduEntity.errCode = pduEntity.data[0];\n        pduEntity.errMsg = getError(pduEntity.data[0]);\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    // 检测是否为输入03和04的返回\n    if (pduEntity.func != 0x03 \u0026\u0026 pduEntity.func != 0x04) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    // 检测：数据长度\n    if (pduEntity.data.length \u003c 1) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    if ((pduEntity.data[0] \u0026 0xff) != pduEntity.data.length - 1) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    if (pduEntity.data.length % 2 != 1) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    var statusList = [];\n\n    var wCount = (pduEntity.data.length - 1) / 2;\n    var byAt = 1;\n    for (var i = 0; i \u003c wCount; i++) {\n        var status = (pduEntity.data[byAt] \u0026 0xff) * 0x100;\n        status += pduEntity.data[byAt + 1] \u0026 0xFF;\n\n        statusList.push(status);\n        byAt += 2;\n    }\n\n    return statusList;\n}\n\n/**\n * 读状态编码器请求\n * @param func\n * @param param\n * @returns {Uint8Array}\n */\nfunction encodeReadStatusRequest(func, param) {\n    // 检测：输入参数释放合法\n    testUserParam(param);\n\n    var pduEntity = newPduEntity();\n    pduEntity.func = func;\n    pduEntity.devAddr = param.devAddr;\n\n    // 检测：是否有流水号参数\n    if (param.sn != undefined \u0026\u0026 param.sn != null) {\n        pduEntity.sn = param.sn;\n    }\n\n    pduEntity.data = new Uint8Array(4);\n    pduEntity.data[0] = param.regAddr / 0x100;\n    pduEntity.data[1] = param.regAddr % 0x100;\n    pduEntity.data[2] = param.regCnt / 0x100;\n    pduEntity.data[3] = param.regCnt % 0x100;\n\n    return encodePdu(pduEntity, param.modbusMode);\n}\n\n/**\n * 数据解析\n * @param pdu\n * @param param\n * @returns {{status: *[]}}\n */\nfunction decodeReadStatusRespond(pdu, param) {\n    // 报文解码\n    var pduEntity = decodePdu(pdu, param.modbusMode);\n\n\n    if (pduEntity.func == 0x80 \u0026\u0026 pduEntity.data.length \u003e 0) {\n        pduEntity.errCode = pduEntity.data[0];\n        pduEntity.errMsg = getError(pduEntity.data[0]);\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    // 检测是否为输入03和04的返回\n    if (pduEntity.func != 0x01 \u0026\u0026 pduEntity.func != 0x02) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    // 检测：数据长度\n    if (pduEntity.data.length \u003c 1) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n    if ((pduEntity.data[0] \u0026 0xff) != pduEntity.data.length - 1) {\n        throw new Error(\"返回的数据格式不正确\");\n    }\n\n    var wCount = pduEntity.data[0];\n    if ((wCount + 1) != pduEntity.data.length) {\n        throw new Error(\"返回的长度不正确\");\n    }\n\n    var status = []\n\n\n    var byStatus = 0;\n    for (var i = 1; i \u003c pduEntity.data.length; i++) {\n        var byAt = pduEntity.data[i];\n        var byBit = 0x01;\n\n        for (var k = 0; k \u003c 8; k++) {\n            status.push((byAt \u0026 byBit) != 0);\n\n            byBit \u003c\u003c= 1;\n        }\n    }\n\n    return status;\n}\n\n/**\n * 出错码信息\n *\n * @param errCode\n * @returns {string}\n */\nfunction getError(code) {\n    if (code == 1) {\n        return \"err=01:非法的功能码\";\n    }\n    if (code == 2) {\n        return \"err=02:非法的数据地址\";\n    }\n    if (code == 3) {\n        return \"err=03:非法的数据值\";\n    }\n    if (code == 4) {\n        return \"err=04:服务器故障\";\n    }\n    if (code == 5) {\n        return \"err=05:确认\";\n    }\n    if (code == 6) {\n        return \"err=06:服务器繁忙\";\n    }\n    if (code == 10) {\n        return \"err=10:网关故障:网关路经是无效的\";\n    }\n    if (code == 11) {\n        return \"err=11:网关故障:目标设备没有响应\";\n    }\n\n    return \"\";\n}\n\n/**\n * 构造PDU实体\n * 注意：使用时，data必须初始化一个具体的长度，中间不可变\n *\n * @param param\n * @returns {{devAddr: number, func: number, data: Uint8Array, errCode: number, errMsg: string, sn: number}}\n */\nfunction newPduEntity() {\n    var pduEntity = {\n        \"sn\": 0,// 流水号\n        \"devAddr\": 0x01,// 地址\n        \"func\": 0x03,// 功能码\n        \"errCode\": 0, // 出错信息\n        \"errMsg\": \"\", //  出错信息\n        \"data\": new Uint8Array(0)// 数据域\n    };\n\n    return pduEntity;\n}\n\n/**\n * 测试数据的合法性\n *\n * @param entity\n */\nfunction testPduEntity(entity) {\n    if (entity.sn == undefined || entity.sn == null) {\n        throw new Error(\"实体字段为空：sn\");\n    }\n    if (entity.devAddr == undefined || entity.devAddr == null) {\n        throw new Error(\"实体字段为空：devAddr\");\n    }\n    if (entity.func == undefined || entity.func == null) {\n        throw new Error(\"实体字段为空：func\");\n    }\n    if (entity.errCode == undefined || entity.errCode == null) {\n        throw new Error(\"实体字段为空：errCode\");\n    }\n    if (entity.errMsg == undefined || entity.errMsg == null) {\n        throw new Error(\"实体字段为空：errMsg\");\n    }\n    if (entity.data == undefined || entity.data == null) {\n        throw new Error(\"实体字段为空：data\");\n    }\n    if (entity.data.length == undefined || entity.data.length == null) {\n        throw new Error(\"实体字段为空：data.length\");\n    }\n}\n\n/**\n * 实例化一个用户输入参数\n * 说明：这是基本的用户输入参数，至少包含这些信息\n *\n * @returns {{devAddr: number, regCnt: number, modbusMode: string, regAddr: number}}\n */\nfunction newUserParam() {\n    var paramEntity = {\n        \"func\": 0x03,// 功能代码\n        \"devAddr\": 0x01,// 设备地址\n        \"regAddr\": 0x00,// 寄存器地址\n        \"regCnt\": 0x00, // 寄存器数量\n        \"modbusMode\": \"\" // ModBus模式\n    };\n\n    return paramEntity;\n}\n\n/**\n * 测试数据的合法性\n *\n * @param entity\n */\nfunction testUserParam(entity) {\n    if (entity.devAddr == undefined || entity.devAddr == null) {\n        throw new Error(\"实体字段为空：devAddr\");\n    }\n    if (entity.regAddr == undefined || entity.regAddr == null) {\n        throw new Error(\"实体字段为空：regAddr\");\n    }\n    if (entity.regCnt == undefined || entity.regCnt == null) {\n        throw new Error(\"实体字段为空：regCnt\");\n    }\n    if (entity.modbusMode == undefined || entity.modbusMode == null) {\n        throw new Error(\"实体字段为空：modbusMode\");\n    }\n}\n\n/**\n * 编码\n * @param entity modbus实体\n * @param mode 工作模式\n *\n * @returns {Uint8Array} 数据报文\n */\nfunction encodePdu(entity, mode) {\n    if (mode == undefined || mode == null) {\n        throw new Error(\"参数为空：mode\");\n    }\n\n    if (mode == \"RTU\") {\n        return encodeRtuPdu(entity);\n    }\n    if (mode == \"TCP\") {\n        return encodeTcpPdu(entity);\n    }\n\n    throw new Error(\"不支持的模式\" + mode);\n}\n\n/**\n * 解码函数\n *\n * @param pdu 报文\n * @param mode 工作模式\n * @returns {{devAddr: number, func: number, data: Uint8Array, errCode: number, errMsg: string, sn: number}|null}\n */\nfunction decodePdu(pdu, mode) {\n    if (mode == undefined || mode == null) {\n        throw new Error(\"参数为空：mode\");\n    }\n\n    if (mode == \"RTU\") {\n        return decodeRtuPdu(pdu);\n    }\n    if (mode == \"TCP\") {\n        return decodeTcpPdu(pdu);\n    }\n\n    throw new Error(\"不支持的模式\" + mode);\n}\n\n/**\n * 编码函数\n *\n * @param entity\n * @returns {Uint8Array}\n */\nfunction encodeRtuPdu(entity) {\n    // 检测：输入参数释放合法\n    testPduEntity(entity);\n\n    var data = new Uint8Array(entity.data.length + 4);\n\n    // Slave Address 11\n    // Function 01\n    // Starting Address Hi 00\n    // Starting Address Lo 13\n    // No. of Points Hi 00\n    // No. of Points Lo 25\n    // Error Check (LRC or CRC) ––\n\n    // 地址码\n    data[0] = entity.devAddr;\n\n    // 功能码\n    data[1] = entity.func;\n\n    // 数据域\n    arraycopy(entity.data, 0, data, 2, entity.data.length);\n\n    // 校验CRC\n    var crc16 = calculateCRC16(data, 0, data.length - 2, 0xFFFF, 0xA001);\n    data[data.length - 2] = crc16 % 0x100;\n    data[data.length - 1] = crc16 / 0x100;\n\n    return data;\n}\n\n/**\n * 解码器函数\n *\n * @param pdu\n * @returns {null|{devAddr: number, func: number, data: Uint8Array, errCode: number, errMsg: string, sn: number}}\n */\nfunction decodeRtuPdu(pdu) {\n    if (pdu == null || pdu == undefined || pdu.length \u003c 4) {\n        throw new Error(\"输入参数pdu异常\");\n    }\n\n    if (pdu.length \u003c 4) {\n        return null;\n    }\n\n    var entity = newPduEntity();\n\n    // 地址码\n    entity.devAddr = pdu[0];\n\n    // 功能码\n    entity.func = pdu[1];\n\n    // 数据域\n    entity.data = new Uint8Array(pdu.length - 4);\n    arraycopy(pdu, 2, entity.data, 0, pdu.length);\n\n    // 校验CRC\n    var crc16 = calculateCRC16(pdu, 0, pdu.length - 2, 0xFFFF, 0xA001);\n    var crcH = crc16 \u0026 0xff;\n    var crcL = (crc16 \u0026 0xff00) \u003e\u003e 8;\n    if (pdu[pdu.length - 1] == crcL \u0026\u0026 pdu[pdu.length - 2] == crcH) {\n        return entity;\n    }\n\n    throw new Error(\"输入参数pdu异常\");\n}\n\n/**\n * 编码函数\n *\n * @param entity\n * @returns {Uint8Array}\n */\nfunction encodeTcpPdu(entity) {\n    // 检测：输入参数释放合法\n    testPduEntity(entity);\n\n    var data = new Uint8Array(entity.data.length + 8);\n\n    // 流水号\n    data[0] = ((entity.sn \u0026 0xff00) \u003e\u003e 8);\n    data[1] = (entity.sn \u0026 0xff);\n\n    // 协议类型\n    data[2] = 0;\n    data[3] = 0;\n\n    // 报文长度\n    var len = entity.data.length + 2;\n    data[4] = (len \u0026 0xff00) \u003e\u003e 8;\n    data[5] = len \u0026 0xff;\n\n    //地址\n    data[6] = entity.devAddr;\n\n    // 功能\n    data[7] = entity.func;\n\n    //数据\n    arraycopy(entity.data, 0, data, 8, entity.data.length);\n\n    return data;\n}\n\n/**\n * 解码器函数\n *\n * @param pdu\n * @returns {null|{devAddr: number, func: number, data: Uint8Array, errCode: number, errMsg: string, sn: number}}\n */\nfunction decodeTcpPdu(pdu) {\n    if (pdu == null || pdu == undefined || pdu.length \u003c 4) {\n        throw new Error(\"输入参数pdu异常\");\n    }\n\n    var entity = new newPduEntity();\n\n    // 流水号\n    var wSn = (pdu[0] \u0026 0xff) * 0x100;\n    wSn += pdu[1] \u0026 0xff;\n    entity.sn = wSn \u0026 0xffff;\n\n    // 协议类型\n    if (pdu[2] != 0 || pdu[3] != 0) {\n        throw new Error(\"协议类型不合法\");\n    }\n\n    // 报文长度\n    var len = (pdu[4] \u0026 0xff) * 0x100;\n    len += pdu[5] \u0026 0xff;\n    if (pdu.length != len + 6) {\n        throw new Error(\"数据长度不匹配\");\n    }\n    if (len \u003c 2) {\n        throw new Error(\"数据长度不合法\");\n    }\n\n    //地址\n    entity.devAddr = pdu[6];\n\n    // 功能\n    entity.func = pdu[7];\n\n    //数据\n    entity.data = new Uint8Array(len - 2);\n    arraycopy(pdu, 8, entity.data, 0, entity.data.length);\n\n    return entity;\n}\n\n","main":"include"}}', '{"description":"Fox-Edge提供的常用Modbus的Core库。\n\n它的目的，是给开发者们，提供一个通用modbus的解码器框架，简化modbus解码器的处理"}', 'status', 'include', 1, 2000, 1744608027153, 1744608027153),
	(11, 'Write Single Status', 'MODBUS', '广州灵狐技术有限公司', 'JavaScript', 'device', '{"decode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction decode() {\n    var param = JSON.parse(fox_edge_param);\n    var  result = decodeWriteSingleStatusRespond(fox_edge_data, param);\n    return JSON.stringify(result);\n}\n\n/**\n * 解码数据\n *\n * @param hexRecv\n * @param param\n * @returns {{}}\n */\nfunction decodeWriteSingleStatusRespond(hexRecv, param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.objectName, \"输入参数不能为空: objectName\");\n    testEmpty(param.objectValue, \"输入参数不能为空: objectValue\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    // 取出对应的设备模型\n    var modelList = fox_edge_model[param.modelName];\n    if (modelList == undefined || modelList == null) {\n        throw new Error(\"找不到对应的设备模型: \" + param.modelName);\n    }\n\n    var pdu = hexToArray(hexRecv);\n\n    var respond = decodeWriteStatusRespond(pdu, param);\n\n    var statusList = [];\n    statusList.push(respond.status);\n\n    var result = decodeStatusValue(modelList, respond.regAddr, 1, statusList);\n    return result;\n}","main":"decode"},"encode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction encode() {\n  var param = JSON.parse(fox_edge_param);\n  return encodeWriteSingleStatusRequest(param);\n}\n\n/**\n * 数据编码\n *\n * @param param\n * @returns {string}\n */\nfunction encodeWriteSingleStatusRequest(param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.objectName, \"输入参数不能为空: objectName\");\n    testEmpty(param.objectValue, \"输入参数不能为空: objectValue\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    // 取出对应的设备模型\n    var modelList = fox_edge_model[param.modelName];\n    if (modelList == undefined || modelList == null) {\n        throw new Error(\"找不到对应的设备模型: \" + param.modelName);\n    }\n\n    // 计算地址信息\n    var regPar = encodeStatusValue(modelList, param.objectName, param.objectValue)\n\n    // 填入地址信息\n    var usrPar = param;\n    usrPar.value = regPar.value;\n    usrPar.regAddr = regPar.regAddr;\n    usrPar.regCnt = 1;\n\n    var pdu = encodeWriteStatusRequest(usrPar);\n    return arrayToHex(pdu);\n}","main":"encode"},"modelName":"modelName"}', '{"description":"说明：读取线圈状态命令（0x05）\n\n--------------------------------------------------------------------------------------------------------------------------\n\n设备参数范例：\n{\n     \"devAddr\": 50,\n     \"modelName\": \"正泰集团股份有限公司|三相电表(DT-SU666)|寄存器定义表\",\n     \"modbusMode\": \"RTU\"\n}\n\n输入参数范例：\n{\n     \"objectName\": “开关电源”,\n     \"objectValue\": true\n}\n"}', 'result', 'exchange', 1, 2000, 1744608027162, 1744608027162),
	(12, 'foxLibs', 'MODBUS', '广州灵狐技术有限公司', 'JavaScript', 'device', '{"include":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 数组的拷贝\n *\n * @param srcUint8Array\n * @param srcPos\n * @param dstUint8Array\n * @param dstPos\n * @param length\n */\nfunction arraycopy(srcUint8Array, srcPos, dstUint8Array, dstPos, length) {\n    var src = srcPos;\n    var dst = dstPos;\n    for (var index = 0; index \u003c length; index++, src++, dst++) {\n        dstUint8Array[dst] = srcUint8Array[src];\n    }\n}\n\n/**\n * 数组转换为hex\n *\n * @param uint8Array\n * @returns {string}\n */\nfunction arrayToHex(uint8Array) {\n    var hex = \"\";\n    for (var i = 0; i \u003c uint8Array.length; i++) {\n        var ch = uint8Array[i].toString(16);\n        hex += padStart(ch, 2, ''0'').toUpperCase();\n    }\n\n    return hex;\n}\n\n/**\n * hex转数组\n * @param hex\n * @returns {Uint8Array}\n */\nfunction hexToArray(hex) {\n    var hex = hex.replace(/\\s+/g, \"\").toUpperCase();\n    var uint8Array = new Uint8Array(hex.length / 2);\n    for (var i = 0; i \u003c uint8Array.length; i++) {\n        uint8Array[i] = parseInt(hex[2 * i] + hex[2 * i + 1], 16);\n    }\n\n    return uint8Array;\n}\n\n/**\n * 替代JS旧版本不支持的padStart函数\n *\n * @param str\n * @param length\n * @param ch\n * @returns {*}\n */\nfunction padStart(str, length, ch) {\n    while (str.length \u003c length) {\n        str = ch + str;\n    }\n\n    return str;\n}\n\n/**\n * CRC16校验\n * 范例：var crc16 = calculateCRC16(data, 0, data.length - 2, 0xFFFF, 0xA001);\n *\n * @param bytes Uint8Array格式的数组\n * @param offset 数组的偏移量\n * @param length 需要计算的长度\n * @param init CRC16的初始值，例如：0x0000\n * @param poly CRC16的多项式，例如：0xA001\n * @returns {number} CRC16\n */\nfunction calculateCRC16(bytes, offset, length, init, poly) {\n    var crc = init;\n    var polynomial = poly;  // This is the polynomial x^16 + x^15 + x^2 + 1\n\n    for (var i = offset; i \u003c length; i++) {\n        crc ^= bytes[i];\n        for (var j = 0; j \u003c 8; j++) {\n            if (crc \u0026 0x0001) {\n                crc = ((crc \u003e\u003e 1) ^ polynomial) \u0026 0xFFFF;\n            } else {\n                crc \u003e\u003e= 1;\n            }\n        }\n    }\n\n    return crc \u0026 0xffff\n}\n\n/**\n * IEEE754浮点数的转换\n * 说明：32位浮点（数默认格式：低位在前，高位在后）\n * 测试范例：45 0f 60 00 数值位2294.0\n * bitsToFloat(0x00, 0x60, 0x0f, 0x45) = 2294.0\n *\n * @param bit3\n * @param bit2\n * @param bit1\n * @param bit0\n * @returns {number}\n */\nfunction bitsToFloat(bit3, bit2, bit1, bit0) {\n    var bits = (bit0 \u003c\u003c 24) | (bit1 \u003c\u003c 16) | (bit2 \u003c\u003c 8) | (bit3);\n    var sign = ((bits \u003e\u003e\u003e 31) == 0) ? 1.0 : -1.0;\n    var e = ((bits \u003e\u003e\u003e 23) \u0026 0xff);\n    var m = (e == 0) ? (bits \u0026 0x7fffff) \u003c\u003c 1 : (bits \u0026 0x7fffff) | 0x800000;\n    var f = sign * m * Math.pow(2, e - 150);\n    return f;\n}\n\n/**\n * 判定是否存在Empty的参数\n *\n * @param arg\n * @returns {boolean}\n */\nfunction testEmpty(arg, error) {\n    if ((arg == undefined || arg == null || arg === '''')) {\n        throw Error(error);\n    }\n}\n","main":"include"}}', '{"description":"Fox-Edge提供的常用公共库JS函数。\n\n它的目的，是提供JS开发者们写解码器的时候，会用到的许多常用函数，避免不必要的重复性开发工作"}', 'status', 'include', 1, 2000, 1744608027168, 1744608027168),
	(13, 'Read Discrete Inputs Status', 'MODBUS', '广州灵狐技术有限公司', 'JavaScript', 'device', '{"decode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction decode() {\n    var param = JSON.parse(fox_edge_param);\n    var  result = decodeReadDiscreteInputsStatuRespond(fox_edge_data, param);\n    return JSON.stringify(result);\n}\n\n/**\n * 解码数据\n *\n * @param hexRecv\n * @param param\n * @returns {{}}\n */\nfunction decodeReadDiscreteInputsStatuRespond(hexRecv, param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.regAddr, \"输入参数不能为空: regAddr\");\n    testEmpty(param.regCnt, \"输入参数不能为空: regCnt\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    // 取出对应的设备模型\n    var modelList = fox_edge_model[param.modelName];\n    if (modelList == undefined || modelList == null) {\n        throw new Error(\"找不到对应的设备模型: \" + param.modelName);\n    }\n\n    var pdu = hexToArray(hexRecv);\n\n    var statusList = decodeReadStatusRespond(pdu, param);\n\n    var result = decodeStatusValue(modelList, param.regAddr, param.regCnt, statusList);\n    return result;\n}","main":"decode"},"encode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction encode() {\n  var param = JSON.parse(fox_edge_param);\n  return encodeReadDiscreteInputsStatusRequest(param);\n}\n\n/**\n * 数据编码\n *\n * @param param\n * @returns {string}\n */\nfunction encodeReadDiscreteInputsStatusRequest(param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.regAddr, \"输入参数不能为空: regAddr\");\n    testEmpty(param.regCnt, \"输入参数不能为空: regCnt\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    var pdu = encodeReadStatusRequest(0x02, param);\n    return arrayToHex(pdu);\n}","main":"encode"},"modelName":"modelName"}', '{"description":"说明：读取线圈状态命令（0x02）\n\n--------------------------------------------------------------------------------------------------------------------------\n\n设备参数范例：\n{\n     \"devAddr\": 50,\n     \"modelName\": \"正泰集团股份有限公司|三相电表(DT-SU666)|寄存器定义表\",\n     \"modbusMode\": \"RTU\"\n}\n\n输入参数范例：\n{\n     \"regCnt\": 10,\n     \"regAddr\": 4146\n}\n"}', 'status', 'exchange', 1, 2000, 1744608027174, 1744608027174),
	(14, 'Read Holding Register', 'MODBUS', '广州灵狐技术有限公司', 'JavaScript', 'device', '{"decode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_data：json string格式 或者 hex string格式的接收数据\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction decode() {\n    var param = JSON.parse(fox_edge_param);\n    var  result = decodeReadHoldingRegisterRespond(fox_edge_data, param);\n    return JSON.stringify(result);\n}\n\n/**\n * 解码数据\n *\n * @param hexRecv\n * @param param\n * @returns {{}}\n */\nfunction decodeReadHoldingRegisterRespond(hexRecv, param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.regAddr, \"输入参数不能为空: regAddr\");\n    testEmpty(param.regCnt, \"输入参数不能为空: regCnt\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    // 取出对应的设备模型\n    var modelList = fox_edge_model[param.modelName];\n    if (modelList == undefined || modelList == null) {\n        throw new Error(\"找不到对应的设备模型: \" + param.modelName);\n    }\n\n    var pdu = hexToArray(hexRecv);\n\n    var statusList = decodeReadRegistersRespond(pdu, param);\n\n    var result = decodeRegistersValue(modelList, param.regAddr, param.regCnt, statusList);\n    return result;\n}","main":"decode"},"encode":{"code":"/* ----------------------------------------------------------------------------\n * Copyright (c) Guangzhou Fox-Tech Co., Ltd. 2020-204. All rights reserved.\n *\n *     This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU General Public License as published by\n * the Free Software Foundation, either version 3 of the License, or\n * (at your option) any later version.\n *\n *     This program is distributed in the hope that it will be useful,\n *     but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU General Public License for more details.\n *\n *     You should have received a copy of the GNU General Public License\n * along with this program.  If not, see \u003chttps://www.gnu.org/licenses/\u003e.\n * --------------------------------------------------------------------------- */\n\n\n/**\n * 编码器的入口函数\n * 全局参数：\n *     fox_edge_param：json string格式的设备参数的合并对象\n * 返回值：\n *   提供给通道的发送数据。根据不同的通道服务，它可能是HEX结构的文本，也可能是JSON结构的对象，请自行根据选定的通道服务进行确认\n */\nfunction encode() {\n  var param = JSON.parse(fox_edge_param);\n  return encodeReadHoldingRegisterRequest(param);\n}\n\n/**\n * 数据编码\n *\n * @param param\n * @returns {string}\n */\nfunction encodeReadHoldingRegisterRequest(param) {\n    // 检查输入参数\n    testEmpty(param.devAddr, \"输入参数不能为空: devAddr\");\n    testEmpty(param.regAddr, \"输入参数不能为空: regAddr\");\n    testEmpty(param.regCnt, \"输入参数不能为空: regCnt\");\n    testEmpty(param.modbusMode, \"输入参数不能为空: modbusMode\");\n    testEmpty(param.modelName, \"输入参数不能为空: modelName\");\n\n    var pdu = encodeReadRegistersRequest(0x03, param);\n    return arrayToHex(pdu);\n}\n","main":"encode"},"modelName":"modelName"}', '{"description":"说明：读取保持寄存器命令（0x03）\n\n--------------------------------------------------------------------------------------------------------------------------\n\n设备参数范例：\n{\n     \"devAddr\": 50,\n     \"modelName\": \"正泰集团股份有限公司|三相电表(DT-SU666)|寄存器定义表\",\n     \"modbusMode\": \"RTU\"\n}\n\n输入参数范例：\n{\n     \"regCnt\": 10,\n     \"regAddr\": 4146\n}\n"}', 'status', 'exchange', 1, 2000, 1744608027180, 1744608027180);
